CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, sha256 TEXT NOT NULL, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), token_sha256 TEXT NOT NULL UNIQUE, csrf_sha256 TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organizations(id UUID PRIMARY KEY, name TEXT NOT NULL CHECK (length(name) BETWEEN 2 AND 160), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(org_id UUID NOT NULL REFERENCES organizations(id), user_id UUID NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK (role IN ('owner','reviewer','viewer')), PRIMARY KEY(org_id,user_id));
CREATE TABLE IF NOT EXISTS projects(id UUID PRIMARY KEY, org_id UUID NOT NULL REFERENCES organizations(id), name TEXT NOT NULL CHECK (length(name) BETWEEN 2 AND 160), notes TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_org_idx ON projects(org_id);
CREATE TABLE IF NOT EXISTS activities(id UUID PRIMARY KEY, org_id UUID NOT NULL REFERENCES organizations(id), project_id UUID NOT NULL REFERENCES projects(id), period TEXT NOT NULL CHECK(length(period) BETWEEN 4 AND 50), activity_type TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('1','2')), quantity TEXT NOT NULL, unit TEXT NOT NULL, factor TEXT NOT NULL, factor_unit TEXT NOT NULL, factor_source TEXT NOT NULL, factor_year INT NOT NULL CHECK(factor_year BETWEEN 1900 AND 2100), methodology TEXT NOT NULL DEFAULT '', kg_co2e TEXT NOT NULL, t_co2e TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS activities_project_idx ON activities(project_id);
CREATE TABLE IF NOT EXISTS claims(id UUID PRIMARY KEY, org_id UUID NOT NULL REFERENCES organizations(id), project_id UUID NOT NULL REFERENCES projects(id), title TEXT NOT NULL CHECK(length(title) BETWEEN 2 AND 180), status TEXT NOT NULL CHECK (status IN ('DRAFT','READY_FOR_REVIEW','REVIEWED_INTERNAL','REJECTED_INTERNAL')), created_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS claims_org_idx ON claims(org_id);
CREATE TABLE IF NOT EXISTS claim_activities(claim_id UUID NOT NULL REFERENCES claims(id), activity_id UUID NOT NULL REFERENCES activities(id), PRIMARY KEY(claim_id,activity_id));
CREATE TABLE IF NOT EXISTS evidence(id UUID PRIMARY KEY, org_id UUID NOT NULL REFERENCES organizations(id), project_id UUID NOT NULL REFERENCES projects(id), uploaded_by UUID NOT NULL REFERENCES users(id), name TEXT NOT NULL, mime TEXT NOT NULL, size_bytes INT NOT NULL CHECK (size_bytes BETWEEN 1 AND 3145728), sha256 TEXT NOT NULL, content BYTEA NOT NULL, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS evidence_org_sha_idx ON evidence(org_id,sha256);
CREATE TABLE IF NOT EXISTS claim_evidence(claim_id UUID NOT NULL REFERENCES claims(id), evidence_id UUID NOT NULL REFERENCES evidence(id), PRIMARY KEY(claim_id,evidence_id));
CREATE TABLE IF NOT EXISTS claim_events(claim_id UUID NOT NULL REFERENCES claims(id), sequence BIGINT NOT NULL CHECK(sequence > 0), event_id UUID NOT NULL UNIQUE, actor_id UUID NOT NULL REFERENCES users(id), event_time TEXT NOT NULL, kind TEXT NOT NULL, payload_text TEXT NOT NULL, previous_hash TEXT NOT NULL, event_hash TEXT NOT NULL, PRIMARY KEY(claim_id, sequence));
CREATE TABLE IF NOT EXISTS audit_events(id UUID PRIMARY KEY, org_id UUID NOT NULL REFERENCES organizations(id), actor_id UUID NOT NULL REFERENCES users(id), action TEXT NOT NULL, subject_id UUID NOT NULL, event_time TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_org_idx ON audit_events(org_id,event_time);
